<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,view:string}>()
const emit=defineEmits<{changed:[]}>()
const certificates=ref<Row[]>([]),proxies=ref<Row[]>([]),nginx=ref<Row|null>(null),busy=ref(false),error=ref(''),notice=ref(''),removing=ref<Row|null>(null)
const freshCert=()=>({id:'',domain:'',provider:'http-01',email:'',dns_token:'',certificate:'',private_key:'',version:0})
const freshProxy=()=>({id:'',domain:'',upstream:'http://127.0.0.1:3000',certificate_id:'',enabled:false,version:0})
const cert=ref(freshCert()),proxy=ref(freshProxy()),options=ref('{\n  "connect_timeout": 10,\n  "read_timeout": 300,\n  "body_limit_mib": 16,\n  "websocket": true\n}')
let alive=true,timer:ReturnType<typeof setInterval>|undefined
async function reload(){const [a,b,n]=await Promise.all([props.api('certificates'),props.api('reverse-proxies'),props.api('gateway/nginx').catch(()=>null)]);if(alive){certificates.value=a;proxies.value=b;nginx.value=n}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function editCert(row:Row){cert.value={...freshCert(),id:row.id,domain:row.domain,provider:row.provider,email:row.email,version:row.version}}
function editProxy(row:Row){proxy.value={...freshProxy(),...Object.fromEntries(Object.keys(freshProxy()).map(k=>[k,row[k]]))} as ReturnType<typeof freshProxy>;options.value=JSON.stringify(row.options??{},null,2)}
function saveCert(){void run(async()=>{const {id,...body}=cert.value;const payload:Row={...body};if(!id)delete payload.version;await props.api('certificates'+(id?'/'+id:''),id?'PUT':'POST',payload);cert.value=freshCert();notice.value='证书配置已保存；自动签发与删除由网关确认。';await reload();emit('changed')})}
function saveProxy(){void run(async()=>{const parsed=JSON.parse(options.value);if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw Error('配置参数必须是 JSON 对象');const {id,...body}=proxy.value;await props.api('reverse-proxies'+(id?'/'+id:''),id?'PUT':'POST',{...body,options:parsed});proxy.value=freshProxy();notice.value='反代已保存，等待 Nginx 原生检查；校验失败保留原配置。';await reload();emit('changed')})}
function remove(){const row=removing.value;if(!row)return;void run(async()=>{await props.api(row.kind+'/'+row.id,'DELETE');removing.value=null;notice.value='已请求删除，网关确认清理后自动移除记录。';await reload();emit('changed')})}
function retry(row:Row){void run(async()=>{await props.api('certificates/'+row.id+'/retry','POST',{});await reload()})}
function bytes(n:number){return new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format((n||0)/1024/1024)+' MiB'}
onMounted(()=>{void run(reload);timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void reload().catch(()=>{})},30000)})
onUnmounted(()=>{alive=false;clearInterval(timer);cert.value=freshCert()})
watch(()=>props.view,()=>{error.value='';notice.value=''})
</script>
<template>
<section class="panel publish-card"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<template v-if="view==='certificates'"><span class="eyebrow">ACME / CERTIFICATES</span><h2>域名证书</h2><p class="muted">支持免费申请、续期、编辑与删除。被节点或反代使用的证书需先解除引用。HTTP-01 需域名指向总管理端、TCP 80 可达；Cloudflare DNS 验证不要求公网 IPv4。</p>
<form @submit.prevent="saveCert"><div class="fields"><label>证书域名<input v-model="cert.domain" required placeholder="proxy.example.com"></label><label>验证方式<select v-model="cert.provider"><option value="http-01">HTTP-01 · 免费自动续期</option><option value="cloudflare">Cloudflare DNS-01 · 免费自动续期</option><option value="manual">手动导入 PEM</option></select></label><label v-if="cert.provider!=='manual'">通知邮箱<input v-model="cert.email" type="email" required></label><label v-if="cert.provider==='cloudflare'">DNS API 令牌<input v-model="cert.dns_token" type="password" autocomplete="off" :required="!cert.id" placeholder="编辑时留空保留现有令牌"></label></div>
<div v-if="cert.provider==='manual'" class="fields"><label>完整证书 PEM<textarea v-model="cert.certificate" :required="!cert.id" placeholder="编辑同域名时留空保留现有证书"></textarea></label><label>私钥 PEM<textarea v-model="cert.private_key" autocomplete="off" :required="!!cert.certificate||!cert.id"></textarea></label></div>
<p v-if="cert.provider!=='manual'" class="muted">点击申请即同意 Let's Encrypt 订户协议，并确认你有权管理此域名。</p><button class="primary" :disabled="busy">{{cert.id?'保存证书修改':cert.provider==='manual'?'验证并导入':'免费一键申请'}}</button><button v-if="cert.id" type="button" class="secondary" @click="cert=freshCert()">取消编辑</button></form>
<div class="table-scroll"><table><thead><tr><th>域名 / 验证</th><th>状态 / 到期</th><th>操作</th></tr></thead><tbody><tr v-for="c in certificates" :key="c.id"><td>{{c.domain}}<small class="block-muted">{{c.provider}}</small></td><td>{{c.deleted_at?'等待清理':c.state}}<small class="block-muted">{{c.expires_at?new Date(c.expires_at).toLocaleDateString():'等待签发'}} {{c.result}}</small></td><td><div v-if="!c.deleted_at" class="row-actions"><button class="text-button" @click="editCert(c)">编辑证书</button><button v-if="c.provider!=='manual'" class="text-button" :disabled="busy||['running','pending'].includes(c.state)" @click="retry(c)">续期 / 重试</button><button class="text-button danger" @click="removing={...c,kind:'certificates'}">删除</button></div></td></tr></tbody></table></div></template>
<template v-else><span class="eyebrow">NGINX / REVERSE PROXY</span><h2>反向代理</h2><div class="gateway-card"><strong>Nginx 版本：{{nginx?.version||'等待网关上报'}}</strong><small class="block-muted">{{nginx?.source==='baota'?'宝塔管理，共享现有网站和管理入口':nginx?.source==='system'?'系统管理的 Nginx':'尚未检测到网关'}}<span v-if="nginx?.checked_at"> · 检测于 {{new Date(nginx.checked_at).toLocaleString()}}</span></small><p class="muted">当前检测到的是网关使用的 Nginx 程序版本；Nginx 的安装、升级、切换和卸载需由其现有管理工具操作，避免中断共用的网站和面板。</p></div><p class="muted">支持公网 HTTP / HTTPS 域名上游及本机应用端口。自动生成 Nginx 配置；JSON 参数可手动修改，实际生效配置可在下方展开查看。管理和订阅域名保留。</p>
<form @submit.prevent="saveProxy"><div class="fields"><label>反代域名<input v-model="proxy.domain" required placeholder="app.example.com"></label><label>上游地址<input v-model="proxy.upstream" required placeholder="https://www.example.com"></label><label>匹配域名的证书<select v-model="proxy.certificate_id" required><option value="" disabled>选择已申请证书</option><option v-for="c in certificates.filter(c=>!c.deleted_at)" :key="c.id" :value="c.id">{{c.domain}} · {{c.state}}</option></select></label><label class="check-label"><input v-model="proxy.enabled" type="checkbox">启用 HTTPS 入口</label></div>
<details :open="!!proxy.id"><summary>手动修改配置参数（JSON）</summary><textarea v-model="options" aria-label="反代配置参数" spellcheck="false" rows="9" class="config-code"></textarea><p class="muted">connect_timeout 1–60 秒；read_timeout 1–600 秒；body_limit_mib 1–64；websocket 布尔值；可选 host_header 域名。参数经校验后生成配置，不执行任意 Nginx 指令。HTTPS 上游验证证书与 SNI。</p></details>
<button class="primary" :disabled="busy">{{proxy.id?'保存反代修改':'创建反向代理'}}</button><button v-if="proxy.id" type="button" class="secondary" @click="proxy=freshProxy()">取消编辑</button></form>
<article v-for="p in proxies" :key="p.id" class="gateway-card"><div class="section-heading"><div><h3>{{p.domain}}</h3><p>{{p.upstream}}</p><small class="muted">{{p.engine||'nginx'}} · {{p.deleted_at?'等待删除':p.state}} · 版本 {{p.reported_version}} / {{p.version}}</small></div><div v-if="!p.deleted_at" class="row-actions"><button class="secondary" @click="editProxy(p)">编辑反代</button><button class="text-button danger" @click="removing={...p,kind:'reverse-proxies'}">删除反代</button></div></div>
<p>请求 {{bytes(p.upload_bytes)}} · 响应 {{bytes(p.download_bytes)}}<small class="block-muted">{{p.usage_reported_at?'计量更新于 '+new Date(p.usage_reported_at).toLocaleString():'等待网关计量'}} · 按完成请求统计 HTTP 字节，约每分钟更新；不含 TLS 开销，长连接结束后入账，与代理用户额度分别记录。</small></p><details><summary>查看生效配置</summary><pre class="config-code">{{p.rendered_config||'等待网关生成配置并回报'}}</pre></details></article></template>
</section>
<div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="确认删除网关配置"><div class="modal-heading"><h2>确认删除</h2></div><div class="form-content"><p>{{removing.domain}}</p><p>删除将清理本项目管理的入口或证书副本。被引用的证书会拒绝删除。</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="danger" :disabled="busy" @click="remove">确认删除</button></div></section></div>
</template>
<style scoped>.gateway-card{margin-top:18px;border:1px solid var(--border,#334155);border-radius:14px;padding:18px}.gateway-card p{overflow-wrap:anywhere}.config-code{width:100%;box-sizing:border-box;white-space:pre-wrap;overflow-wrap:anywhere;font-family:monospace;max-height:420px;overflow:auto}.row-actions{flex-wrap:wrap}</style>
